<?php declare(strict_types=1); $e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8'); $appName=getenv('APP_NAME')?:'Academic Timetable Optimiser'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Courses and units · <?= $e($appName) ?></title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-50 text-slate-900"><div class="min-h-screen lg:flex"><aside class="bg-slate-950 text-white lg:w-64"><div class="border-b border-white/10 px-6 py-6"><p class="text-xs uppercase tracking-widest text-cyan-300">Academic planning</p><a href="/" class="mt-2 block text-lg font-semibold"><?= $e($appName) ?></a></div><nav class="flex flex-wrap gap-2 p-4 lg:flex-col"><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/">Overview</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/teachers">Teachers</a><a aria-current="page" class="rounded-lg bg-white/10 px-3 py-2 text-sm" href="/demand">Courses & units</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/calendar">Academic calendar</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/rooms">Rooms</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/week">Week structure</a></nav></aside><main class="min-w-0 flex-1"><header class="border-b bg-white px-6 py-5 lg:px-10"><p class="text-sm text-slate-500">Curriculum structure</p><h1 class="text-2xl font-semibold">Courses and units</h1><p class="mt-1 text-sm text-slate-600">A course can contain shared units; set delivery dates per course and unit, not per teacher.</p></header><div class="mx-auto max-w-7xl space-y-6 px-6 py-8 lg:px-10">
<?php if($flash): ?><div role="status" class="rounded-xl border p-4 text-sm <?= $flash['type']==='success'?'border-emerald-200 bg-emerald-50':'border-rose-200 bg-rose-50' ?>"><?= $e($flash['message']) ?></div><?php endif; ?>
<div class="grid gap-5 xl:grid-cols-3"><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Add course</h2><form method="post" action="/demand/save" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="course"><label class="block text-sm">Course name<input required name="name" maxlength="160" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="block text-sm">Code (optional)<input name="code" maxlength="40" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="block text-sm">Course type<select name="course_type" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="vocational">Vocational</option><option value="standalone">Standalone</option></select></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Total hours<input type="number" min="0" step="0.25" name="total_hours" value="0" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="text-sm">Total credits<input type="number" min="0" step="0.5" name="total_credits" value="0" class="mt-1 block w-full rounded-lg border px-3 py-2"></label></div><label class="flex gap-2 text-sm"><input type="checkbox" name="requires_english_maths">Requires English/Maths delivery</label><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Save course</button></form></section>
<section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Add unit</h2><form method="post" action="/demand/save" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="unit"><label class="block text-sm">Unit name<input required name="name" maxlength="160" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="block text-sm">Code (optional)<input name="code" maxlength="40" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Total hours<input type="number" min="0" step="0.25" name="total_hours" value="0" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="text-sm">Total credits<input type="number" min="0" step="0.5" name="total_credits" value="0" class="mt-1 block w-full rounded-lg border px-3 py-2"></label></div><label class="block text-sm">Default session length (minutes)<input type="number" min="15" max="240" step="15" name="default_session_length_minutes" value="60" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Save unit</button></form></section>
<section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Schedule a course unit</h2><form method="post" action="/demand/save" class="mt-4 space-y-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="kind" value="offering"><label class="block text-sm">Course<select required name="course_id" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="">Choose course</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= $e($c['name']) ?></option><?php endforeach; ?></select></label><label class="block text-sm">Unit<select required name="unit_id" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="">Choose unit</option><?php foreach($units as $u): ?><option value="<?= (int)$u['id'] ?>"><?= $e(($u['code']?$u['code'].' · ':'').$u['name']) ?></option><?php endforeach; ?></select></label><label class="block text-sm">Academic year<select required name="academic_year_id" id="year" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="">Choose year</option><?php foreach($years as $y): ?><option value="<?= (int)$y['id'] ?>" data-start="<?= $e($y['starts_on']) ?>" data-end="<?= $e($y['ends_on']) ?>"><?= $e($y['name']) ?></option><?php endforeach; ?></select></label><label class="block text-sm">Term (optional)<select name="term_id" id="term" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="">Whole year / no term</option><?php foreach($terms as $t): ?><option value="<?= (int)$t['id'] ?>" data-year="<?= (int)$t['academic_year_id'] ?>" data-start="<?= $e($t['starts_on']) ?>" data-end="<?= $e($t['ends_on']) ?>"><?= $e($t['name']) ?> (<?= $e($t['starts_on']) ?>–<?= $e($t['ends_on']) ?>)</option><?php endforeach; ?></select></label><label class="block text-sm">Delivery pattern<select required name="delivery_pattern" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="semesterised_fat">Semesterised (FAT)</option><option value="weekly_long">Weekly (Long)</option></select></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Starts<input required type="date" name="starts_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label><label class="text-sm">Ends<input required type="date" name="ends_on" class="mt-1 block w-full rounded-lg border px-2 py-2"></label></div><div class="grid grid-cols-2 gap-3"><label class="text-sm">Learners<input type="number" min="0" max="5000" name="cohort_size" value="0" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="text-sm">Session minutes<input type="number" min="15" max="240" step="15" name="session_length_minutes" value="60" class="mt-1 block w-full rounded-lg border px-3 py-2"></label></div><label class="block text-sm">Required room type<input name="required_room_type" maxlength="100" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Save offering</button></form></section></div>
<div class="grid gap-5 lg:grid-cols-2"><section class="rounded-xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Courses</h2></div><div class="divide-y"><?php foreach($courses as $c): ?><div class="flex justify-between gap-3 p-4 text-sm"><div><strong><?= $e($c['name']) ?></strong><span class="ml-2 rounded-full bg-slate-100 px-2 py-1 text-xs"><?= $e(ucfirst($c['course_type'])) ?></span><p class="mt-1 text-slate-500"><?= number_format((float)$c['total_hours'],2) ?> hours · <?= number_format((float)$c['total_credits'],1) ?> credits<?= (int)$c['requires_english_maths']?' · English/Maths':'' ?></p></div><span class="text-slate-500"><?= $e($c['code']??'') ?></span></div><?php endforeach; ?><?php if(!$courses): ?><p class="p-5 text-sm text-slate-500">No courses added.</p><?php endif; ?></div></section><section class="rounded-xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Units</h2></div><div class="divide-y"><?php foreach($units as $u): ?><div class="p-4 text-sm"><strong><?= $e($u['name']) ?></strong><p class="mt-1 text-slate-500"><?= number_format((float)$u['total_hours'],2) ?> hours · <?= number_format((float)$u['total_credits'],1) ?> credits · <?= (int)$u['default_session_length_minutes'] ?> min sessions</p></div><?php endforeach; ?><?php if(!$units): ?><p class="p-5 text-sm text-slate-500">No units added.</p><?php endif; ?></div></section></div>
<section class="overflow-hidden rounded-xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Course unit offerings</h2><p class="mt-1 text-sm text-slate-500">A unit can appear on multiple courses with different dates and delivery patterns.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[800px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3">Course</th><th class="p-3">Unit</th><th class="p-3">Delivery</th><th class="p-3">Academic period</th><th class="p-3">Dates</th><th class="p-3">Learners</th></tr></thead><tbody class="divide-y"><?php foreach($offerings as $o): ?><tr><td class="p-3 font-medium"><?= $e($o['course_name']) ?></td><td class="p-3"><?= $e($o['unit_name']) ?></td><td class="p-3"><?= $o['delivery_pattern']==='semesterised_fat'?'Semesterised (FAT)':'Weekly (Long)' ?></td><td class="p-3"><?= $e($o['year_name']) ?><?= $o['term_name']?' · '.$e($o['term_name']):'' ?></td><td class="p-3"><?= $e($o['starts_on']) ?>–<?= $e($o['ends_on']) ?></td><td class="p-3"><?= (int)$o['cohort_size'] ?></td></tr><?php endforeach; ?><?php if(!$offerings): ?><tr><td colspan="6" class="p-8 text-center text-slate-500">No course unit offerings configured.</td></tr><?php endif; ?></tbody></table></div></section>
</div></main></div></body></html>
